--

CREATE TABLE public.movimientos (
    id integer NOT NULL,
    producto_id integer NOT NULL,
    factura_id integer,
    requisicion_id integer,
    venta_id integer,
    venta_sync_uuid text,
    tipo character varying(30) NOT NULL,
    cantidad double precision NOT NULL,
    cantidad_anterior double precision DEFAULT 0,
    cantidad_nueva double precision DEFAULT 0,
    peso_total double precision DEFAULT 0,
    registrado_por character varying(100),
    observaciones text,
    almacen character varying(50),
    fecha_movimiento timestamp with time zone DEFAULT now(),
    created_at timestamp with time zone DEFAULT now(),
    fecha_traslado timestamp with time zone,
    motivo_no_validacion text
);


ALTER TABLE public.movimientos OWNER TO postgres;

--
-- Name: COLUMN movimientos.fecha_traslado; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.movimientos.fecha_traslado IS 'Fecha de negocio del traslado: fecha_creacion de su requisicion. NULL para ventas, ajustes y produccion. Las vistas de historial usan COALESCE(fecha_traslado, fecha_movimiento). NO usarla como cursor de orden para el recalculo de stock: ese va por fecha_movimiento, porque la cadena cantidad_anterior -> cantidad_nueva solo es valida en orden de insercion.';


--
-- Name: COLUMN movimientos.motivo_no_validacion; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.movimientos.motivo_no_validacion IS 'Motivo por el que la entrada pendiente aun no se ha validado. Se limpia al vincular la factura.';


